style.css:
/* styles.css */

/* Change the background color of every webpage to light blue */
body {
    background-color: #ADD8E6 !important; /* Light blue color */
    color: #333; /* Dark gray text color for contrast */
}

/* Ensure text is readable */
h1, h2, h3, h4, h5, h6, p {
    text-shadow: 1px 1px 2px rgba(255, 255, 255, 0.7); /* Text shadow for readability */
}

/* Remove default margin from body */
body {
    margin: 0;
    padding: 0;
    overflow: hidden; /* Prevent scrollbars if content overflows */
}

/* Style links for better visibility */
a {
    color: #0000EE; /* Link color */
    text-decoration: underline; /* Underline links */
}

a:hover {
    color: #FF0000; /* Change link color on hover */
}
